/bin/zsh -lc "python3 - <<'PY'
import json,urllib.request,pathlib,concurrent.futures
files=json.load(open('work/downloads.json'))
def get(f):
 p=pathlib.Path('work/randy-downloads')/f['name']
 try:
  urllib.request.urlretrieve(f['ref']['download_url'],p)
  return (f['name'],p.stat().st_size)
 except Exception as e: return (f['name'],type(e).__name__)
for result in concurrent.futures.ThreadPoolExecutor(max_workers=6).map(get,files): print(*result)
